}
func parseCSV(body string) formula.ExternalResult {
	// 어느 인코딩인지 밝히고 오는 파일은 그대로 읽는다. 밝히는 표시를 떼는 자리와
	// 여는 자리가 하나여야 업로드로 들어온 같은 파일과 같은 표가 나온다.
	body = string(delimited.ToUTF8([]byte(body)))
	reader := csv.NewReader(strings.NewReader(body))
	reader.Comma = delimited.Delimiter(body)
	reader.FieldsPerRecord = -1
	reader.LazyQuotes = true
	records, err := reader.ReadAll()
	if err != nil {
		return formula.ExternalResult{Err: &formula.Error{Code: "#VALUE!", Message: "CSV 를 읽지 못했습니다: " + short(err.Error())}}
	}
	columns := 0
	for _, record := range records {
		if len(record) > columns {
			columns = len(record)
		}
	}
	if len(records) == 0 || columns == 0 {
		return formula.ExternalResult{}
	}
	if len(records)*columns > maxCSVCells {
		return formula.ExternalResult{Err: &formula.Error{Code: "#NUM!", Message: fmt.Sprintf("IMPORTDATA 는 최대 %d칸까지 가져옵니다", maxCSVCells)}}
	}
	values := make([]any, 0, len(records)*columns)
	for _, record := range records {
		for column := 0; column < columns; column++ {
			if column >= len(record) {
				values = append(values, nil)
				continue
			}
			// 수로 읽는 자는 업로드 가져오기와 같은 것 하나뿐이다 — 스프레드시트가
			// 수라고 부르는 것이지 Go 가 수라고 부르는 것이 아니다. 16진수도,
			// NaN 도, 밑줄로 자리를 가른 것도 수가 아니고, 우편번호의 "00123"
			// 과 스무 자리 계좌번호는 수로 담으면 적힌 것과 달라지므로 글자다.
			text := strings.TrimSpace(record[column])
			if number, ok := delimited.Number(text); ok {
				values = append(values, number)
			} else {
				values = append(values, record[column])
			}
		}
	}
	return formula.ExternalResult{Rows: len(records), Columns: columns, Values: values}
}

func stringList(value any) []string {
	switch typed := value.(type) {
	case []string:
		return typed
	case []any:
		out := make([]string, 0, len(typed))
		for _, item := range typed {
			if text, ok := item.(string); ok {
				out = append(out, text)
			}
		}
		return out
	case string:
		return strings.Split(typed, ",")
	}
	return nil
func parseScalar(value string) any {
	// A delimited file that came from a spreadsheet keeps formula-looking text
	// behind an apostrophe. Reading it as part of the value turns a phone
	// number into '+82-10-1234-5678 on the way back in.
	value = unguardDelimitedValue(value)
	lower := strings.ToLower(value)
	if lower == "true" {
		return true
	}
	if lower == "false" {
		return false
	}
	// 수로 읽는 자는 수식 엔진과 격자가 함께 쓰는 자여야 한다. Go 의
	// ParseFloat 는 그보다 넓어 "NaN"·"Inf"·"1_000"·"0x1p4" 까지 받는데,
	// pandas 나 R 이 내보낸 CSV 에는 빠진 값이 "NaN" 이라는 글자로 들어 있다.
	// 그 한 칸이 부동소수점 NaN 이 되면 JSON 으로 적을 수 없어 파일이 통째로
	// 들어오지 못했고, "1_000" 은 조용히 1000 이 되어 적힌 것과 다른 값을
	// 남겼다. 그런 것은 수가 아니라 글자로 두어야 파일에 적힌 대로 남는다.
	// 앞자리 0 과 열여섯 자리 넘는 번호를 글자로 두는 것까지 합쳐 그 자는
	// delimited.Number 하나다 — IMPORTDATA 가 같은 자를 써야 같은 파일이 어느
	// 문으로 들어오든 같은 표가 된다.
	if number, ok := delimited.Number(value); ok {
		return number
	}
	return value
func unguardDelimitedValue(text string) string {
	if len(text) > 1 && text[0] == '\'' && needsDelimitedGuard(text[1:]) {
		return text[1:]
	}
	return text
}
func safeFileName(value string) string {
	value = strings.TrimSpace(value)
	replacer := strings.NewReplacer("/", "_", "\\", "_", ":", "_", "\x00", "")
	value = replacer.Replace(value)
	if value == "" {
		return "kanpic"
	}
	return value
}
