func parseDelimited(fileName, title, format string, data []byte) (ParsedWorkbook, error) {
	// 올라온 파일의 크기는 옮겨 읽기 전에 재 둔다 — UTF-16 은 UTF-8 로 옮기면
	// 대개 절반으로 줄어, 미리보기가 사용자가 고른 파일보다 작은 수를 말하게 된다.
	sizeBytes := len(data)
	data = delimited.ToUTF8(data)
	if !utf8.Valid(data) {
		return ParsedWorkbook{}, errors.New("CSV must be UTF-8 encoded")
	}
	delimiter := '\t'
	if format == "csv" {
		delimiter = detectDelimiter(data)
	}
	reader := csv.NewReader(bytes.NewReader(data))
	reader.Comma = delimiter
	reader.FieldsPerRecord = -1
	reader.TrimLeadingSpace = false
	cells := make([]workbook.CellInput, 0)
	rows, maxColumns, textNumbers := 0, 0, 0
	for {
		record, err := reader.Read()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return ParsedWorkbook{}, fmt.Errorf("parse delimited row %d: %w", rows+1, err)
		}
		rows++
		if len(record) > maxColumns {
			maxColumns = len(record)
		}
		for column, raw := range record {
			if raw == "" {
				continue
			}
			scalar := parseScalar(raw)
			if text, ok := scalar.(string); ok && looksLikeNumberStoredAsText(text) {
				textNumbers++
			}
			value, err := json.Marshal(scalar)
			if err != nil {
				return ParsedWorkbook{}, err
			}
			cells = append(cells, workbook.CellInput{Row: rows, Column: column + 1, Value: value})
			if len(cells) > MaxImportCells {
				return ParsedWorkbook{}, errors.New("import exceeds one million non-empty cells")
			}
		}
	}
	name := "Sheet1"
	warnings := []string{}
	// 쉼표나 통화 기호가 붙은 값은 글자로 들어온다. =SUM 이 조용히 빼고
	// 셈하므로 합계가 작게 나오는데, 무엇이 빠졌는지는 아무 데도 적히지
	// 않는다. 가져오기 전에 몇 칸인지 알려 주고 고치는 자리를 가리킨다.
	if textNumbers > 0 {
		warnings = append(warnings, fmt.Sprintf("숫자처럼 보이지만 글자로 담긴 칸이 %d개 있습니다. 가져온 뒤 데이터 › 데이터 정리 › 텍스트로 저장된 숫자로 고칠 수 있습니다.", textNumbers))
	}
	preview := Preview{FileName: fileName, Format: format, SizeBytes: sizeBytes, Sheets: []SheetPreview{{Name: name, Rows: rows, Columns: maxColumns, NonEmptyCells: len(cells)}}, TotalCells: len(cells), Warnings: warnings}
	return ParsedWorkbook{Title: title, Format: format, Sheets: []workbook.ImportSheet{{Name: name, Cells: cells}}, Preview: preview}, nil
}

